content.css:
html,
body {
  margin: 0;
  padding: 0;
  overflow: hidden;
  font-family: "Segoe UI", wf_standard-font, -apple-system, BlinkMacSystemFont, sans-serif;
  -webkit-font-smoothing: antialiased;
}
.cv-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: #8A93A5;
  font-size: 11px;
}
svg .cv-dim {
  opacity: 0.32;
}
svg text.cv-picked {
  fill: #1A2233;
  font-weight: 700;
}
svg {
  display: block;
}
